import AppKit

/// The agent's silence tool: the read half of Remove Silences.
///
/// `detect_silence` is an APP-STATE tool, not an op — it changes nothing and
/// registers no undo step. It exists because the detection is Swift's (the
/// waveform peaks the package caches are not in the model, and the core does
/// no sample work at all — spec §7), so an agent that could only call
/// `ripple_delete_ranges` would have to invent the ranges from nothing. The
/// pair is deliberate and mirrors the sheet exactly: `detect_silence` is what
/// `SilenceSheetController` shows in its live readout, and
/// `ripple_delete_ranges` is what its Remove button sends.
///
/// It stays on the MAIN thread, and so out of `AgentServer.offMainTools`,
/// because that set's criterion is "waits for something the main thread has
/// to deliver or must not be doing", not "touches the disk":
/// `consolidate_media` copies whole media libraries on main and says why, and
/// `import_captions` parses a file on main for the same reason. Reading a few
/// hundred KB of `cache/peaks/<id>.bin` and making one arithmetic pass over
/// it waits on nothing and has no completion to deliver, and being off main
/// would cost an `onMain` hop for every document touch — which is where the
/// real bugs in this file's neighbours have been.
extension AgentServer {

    /// The longest a duration argument may be, `snappedTick`'s own ±9.0e15:
    /// past it `refine`'s `run.start + padding` overflows. Finding 1 above.
    /// Not private: `AgentCatalog+Audio` PUBLISHES it as both durations'
    /// `maximum`, so the bound a caller reads and the bound the handler
    /// enforces are one number (the second sceptic pass, road map 4 §8).
    static let durationCeiling = 9_000_000_000_000_000

    /// `detect_silence` — Clip ▸ Remove Silences…
    /// (`SilenceSheetController`, whose four controls are these four
    /// arguments and whose live "N cuts · removes M:SS" line is this
    /// result). Nothing is edited: feed `ranges` to `ripple_delete_ranges`
    /// to make the cut, which is what that sheet's button does. The
    /// `protected_nests` note is the tool's spelling of the sheet's nest note.
    ///
    /// Quiet is measured IN THE MIX — the peak bucket times the plan's audio
    /// envelope at that tick — so a clip turned down, faded, ducked, muted or
    /// silenced by another track's solo is quiet here exactly as it is in the
    /// speakers. A tick no clip in scope covers is not a candidate at all: a
    /// hole in the timeline is not dead air to be removed.
    func detectSilence(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let clips = try optionalClipsArg(a, "clips", document)
        // `clips` is the sheet's scope popup, spelled as the thing an agent
        // actually has: ids. Naming any runs the popup's "Selected clips"
        // over exactly those — `read` takes a selection override for this
        // very reason — and omitting the key takes the sheet's own opening
        // rule, which is the document's selection when it holds anything
        // with sound and everything audible otherwise. The result reports
        // which of the two answered, because "nothing was found" and
        // "nothing was looked at" are different answers and no caller can
        // tell them apart from an empty list.
        guard let input = SilenceDetector.read(from: document, selection: clips.map { Set($0) })
        else {
            throw ToolError(
                message: "The project's audio plan could not be read, so there is nothing to "
                    + "measure silence against.")
        }
        let (settings, modeNote) = try silenceSettings(
            a, scope: clips == nil ? input.defaultScope : .selected,
            voiceAvailable: input.voiceAvailable)
        let outcome = SilenceDetector.detect(input, settings: settings)

        var result: [String: Any] = [
            "ok": true,
            "ranges": outcome.spans.map { [$0.start, $0.end] },
            "count": outcome.spans.count,
            "removes": outcome.removed,
            "scope": outcome.scope.rawValue,
            "clips": outcome.clips.map { Int($0) },
            "threshold_db": settings.thresholdDB,
            "min_length": settings.minLength,
            "padding": settings.padding,
            "mode": outcome.mode.rawValue,
            "voice_confidence": settings.voiceConfidence,
            "judged_by_level": outcome.judgedByLevel.map { Int($0) },
            // The same answers by CLIP (#107): two clips of one file can be
            // judged, and proposed, differently.
            "judged_by_level_clips": outcome.judgedByLevelClips.map { Int($0) },
        ]
        if !outcome.proposedByMixClips.isEmpty {
            result["proposed_by_mix_clips"] = outcome.proposedByMixClips.map { Int($0) }
        }
        var notes: [String] = []
        if let modeNote { notes.append(modeNote) }
        // Two things worth a sentence rather than a silent zero, because both
        // read as "there is no dead air here" and neither is that.
        if outcome.clips.isEmpty {
            notes.append(
                settings.scope == .selected
                ? "None of those clips plays any sound, so nothing was analysed."
                : "Nothing in this timeline is audible, so nothing was analysed.")
        }
        // Both waiters fold into ONE key, `pending_peaks` — the union of what
        // the level test and the voice test are each still waiting on — so a
        // caller that only ever read that key still knows to call again.
        let pendingPeaks = Set(outcome.pendingMedia)
        let pendingUnion = outcome.mode == .voice
            ? pendingPeaks.union(outcome.voicePending) : pendingPeaks
        if !pendingUnion.isEmpty {
            result["pending_peaks"] = pendingUnion.sorted().map { Int($0) }
            // "Nothing inside them is proposed for removal" is a PROMISE about
            // the ranges in this same reply, so it is made only about the
            // media it holds for. A media with no peaks is never quiet in
            // LEVEL mode, so there it holds for every waiter; in VOICE mode a
            // media whose waveform is missing but whose speech has landed is
            // judged by the model and spans inside it ARE proposed — and the
            // sentence used to deny exactly the ranges it was printed beside
            // (the reader review, road map 4 §8, R3·1).
            let waiter = outcome.mode == .voice ? Set(outcome.voicePending) : pendingPeaks
            // And the promise is made about what this ANSWER shows, not about
            // the mode: the gain FLOOR is asked before either cache
            // (`SilenceDetector.isQuiet`), so a clip the mix has turned down,
            // faded, ducked or muted is quiet with nothing on disk at all and
            // its spans are right here (the reader review, road map 4 §8,
            // finding 2). Whatever the answer proposes inside is dropped from
            // the promise, and the clips it is proposed inside are named in
            // their own clause (#107).
            let proposedInside = waiter.intersection(outcome.proposedMedia)
            let blocked = waiter.subtracting(proposedInside)
            let waveformOnly = pendingUnion.subtracting(waiter)
            var waiting =
                "Analysis is still running for \(pendingUnion.count) media file(s); call "
                + "again in a moment."
            if !blocked.isEmpty {
                waiting += blocked.count == pendingUnion.count
                    ? " Nothing inside them is proposed for removal."
                    : " Nothing inside \(blocked.count) of them is proposed for removal."
            }
            let mixInside = Self.clipIDs(outcome.mixAnswers(inside: waiter))
            if mixInside.count == 1 {
                waiting +=
                    " Clip \(mixInside[0]) holds spans that ARE proposed here: the mix turns "
                    + "it down far enough to be quiet before either cache is asked."
            } else if mixInside.count > 1 {
                waiting +=
                    " Clips \(Self.listed(mixInside)) hold spans that ARE proposed here: the "
                    + "mix turns them down far enough to be quiet before either cache is asked."
            }
            if !waveformOnly.isEmpty {
                // The mirror image of the promise above, and it needs the
                // same intersection (the reader review's second sceptic pass,
                // road map 4 §8). "Spans inside them ARE proposed here" is a
                // claim about ranges in this very reply, so a waveform waiter
                // the answer proposes NOTHING inside — every clip of it holds
                // no voice, so the missing waveform blocks the lot — must not
                // be told it has them.
                let proposedHere = waveformOnly.intersection(outcome.proposedMedia)
                let silentHere = waveformOnly.subtracting(proposedHere)
                let ending: String
                if silentHere.isEmpty {
                    ending = ", so spans inside them ARE proposed here."
                } else if proposedHere.isEmpty {
                    ending = ", and nothing inside them is proposed here."
                } else {
                    ending =
                        ", so spans inside \(proposedHere.count) of them ARE proposed here "
                        + "and nothing inside the other \(silentHere.count) is."
                }
                waiting +=
                    " For \(Self.subject(waveformOnly.count, of: pendingUnion.count)) it is the "
                    + "WAVEFORM that has not landed, which in voice mode decides only a clip "
                    + "holding no voice" + ending
                // And where those spans are the FLOOR's rather than the
                // model's, name the clip (#107): a clip that holds no voice
                // is proposed without its waveform only because the mix
                // already turned it down, and another clip of the same file
                // the mix left alone is not. No `voicePending` arm is needed
                // here — a voice waiter is in `waiter` above and never in
                // `waveformOnly`.
                let mixOnly = Self.clipIDs(outcome.mixAnswers(inside: waveformOnly))
                if mixOnly.count == 1 {
                    waiting +=
                        " Clip \(mixOnly[0]) is proposed only where the mix already turns it "
                        + "down far enough to be quiet."
                } else if mixOnly.count > 1 {
                    waiting +=
                        " Clips \(Self.listed(mixOnly)) are proposed only where the mix "
                        + "already turns them down far enough to be quiet."
                }
            }
            notes.append(waiting)
        }
        if !outcome.voicePending.isEmpty {
            result["voice_pending"] = outcome.voicePending.map { Int($0) }
        }
        let byLevel = outcome.judgedByLevelClips
        if byLevel.count == 1 {
            notes.append("Clip \(byLevel[0]) holds no voice and was judged by level.")
        } else if byLevel.count > 1 {
            notes.append(
                "Clips \(Self.listed(byLevel)) hold no voice and were judged by level.")
        }
        // The sheet's nest note, spelled for an agent (#352): a candidate
        // held back at a nest's wall, dropped without a word, reads as "there
        // is no dead air here". A listed nest clip is one a quiet run of the
        // SCOPED voices crossed (`SilenceDetector+Walls.swift`'s
        // `excludingNests`); the nest's own sound is not tested, so it MAY
        // hold dead air, and the reader is told to look, not that it does.
        // Last, as the sheet puts its nest note last.
        if !outcome.protectedNests.isEmpty {
            let ids = outcome.protectedNests
            result["protected_nests"] = ids.map { Int($0) }
            let lead =
                ids.count == 1
                ? "Quiet that runs across nest clip \(ids[0]) is left alone"
                : "Quiet that runs across nest clips \(Self.listed(ids)) is left alone"
            let reach =
                ids.count == 1
                ? "To look for dead air inside it, call set_scope with clip \(ids[0]), then "
                    + "detect_silence again."
                : "To look for dead air inside them, call set_scope with each clip, then "
                    + "detect_silence again."
            notes.append(
                lead + ": a nest plays from its first frame, so cutting into one would "
                    + "strand the rest of it. " + reach)
        }
        if !notes.isEmpty { result["note"] = notes.joined(separator: " ") }
        result["project"] = summary(document)
        return try jsonResult(result)
    }

    /// "that file" / "them" / "2 of them", so a clause about SOME of the
    /// waiters never says "the rest" of a sentence that was not printed
    /// (the reader review, road map 4 §8, finding 4).
    private static func subject(_ count: Int, of total: Int) -> String {
        count == total ? (count == 1 ? "that file" : "them") : "\(count) of them"
    }

    /// The distinct clip ids of some voices' answers, ascending — the tool
    /// names a clip by id, as `Transcriber+Jobs` tags one (#107).
    private static func clipIDs(_ answers: [SilenceDetector.VoiceAnswer]) -> [UInt32] {
        Set(answers.map { $0.clip }).sorted()
    }

    /// "3, 7, 9".
    private static func listed(_ ids: [UInt32]) -> String {
        ids.map { String($0) }.joined(separator: ", ")
    }

    /// The three numbers, read in the sheet's own units and refused by name.
    ///
    /// The sheet clamps its controls to `Settings`' published ranges because
    /// a slider must land somewhere; a tool does not, and clamping an
    /// argument silently would report a detection the caller did not ask
    /// for. What is refused here is what is not a level or not a length at
    /// all — everything else is passed through and named back in the result,
    /// so a caller reading `threshold_db` sees what actually ran.
    private func silenceSettings(
        _ a: [String: Any], scope: SilenceDetector.Scope, voiceAvailable: Bool
    ) throws -> (SilenceDetector.Settings, String?) {
        var settings = SilenceDetector.Settings(scope: scope)
        var note: String?
        if let modeString = try stringArg(a, "mode") {
            guard let mode = SilenceDetector.Mode(rawValue: modeString) else {
                throw ToolError(
                    message: "mode must be \"voice\" or \"level\".")
            }
            if mode == .voice, !voiceAvailable {
                throw ToolError(
                    message: "The voice model could not be used; call with mode: \"level\".")
            }
            settings.mode = mode
        } else if !voiceAvailable {
            settings.mode = .level
            note = "The voice model could not be used, so quiet is judged by level."
        }
        if let voiceConfidence = try doubleArg(a, "voice_confidence") {
            guard settings.mode == .voice else {
                throw ToolError(
                    message: "voice_confidence only applies in mode: \"voice\".")
            }
            guard voiceConfidence.isFinite,
                SilenceDetector.Settings.voiceConfidenceRange.contains(voiceConfidence)
            else {
                throw ToolError(
                    message: "voice_confidence must be a number in "
                        + "\(SilenceDetector.Settings.voiceConfidenceRange.lowerBound)…"
                        + "\(SilenceDetector.Settings.voiceConfidenceRange.upperBound).")
            }
            settings.voiceConfidence = voiceConfidence
        }
        if let thresholdDB = try doubleArg(a, "threshold_db") {
            // Above full scale every bucket of every recording counts as
            // quiet and the whole timeline comes back as one candidate.
            // Peaks are unclamped and a hot source really does read over
            // 1.0, so this is a caller's mistake — a level in gain, or a
            // sign forgotten — rather than an impossible number.
            guard thresholdDB.isFinite, thresholdDB <= 0 else {
                throw ToolError(
                    message: "threshold_db must be a level at or below 0 dBFS (full scale); "
                        + "the default is \(SilenceDetector.Settings.defaultThresholdDB).")
            }
            settings.thresholdDB = thresholdDB
        }
        // Both lengths are DURATIONS, and a duration is not a position: they
        // are read as given, by the whole-number reader, and are NOT snapped
        // to the frame grid. The sheet's own two fields are not snapped
        // either (`SilenceSheetController.silenceSettings`'
        // `ReelTime.ticks(seconds:)`) and this tool exists to mirror it; the
        // frame rule stays where it belongs, on the span BOUNDS `refine`
        // produces, so no sub-frame time reaches an op from here. Going
        // through `optionalTimeArg` cost that mirror at the DEFAULT rate:
        // at 30 fps it ran `padding: 30000` — the sheet's own 0.05 s — as
        // 40000, ran `min_length: 45000` as 40000, and dropped
        // `padding: 9999` to 0, cutting the material the caller asked to
        // keep (the reader review, road map 4 §8, R1·1).
        //
        // What `optionalTimeArg` DID carry and a duration still needs is its
        // CEILING: `refine` adds the padding to a run's start, and a padding
        // at `Int64.max` overflowed and killed the app rather than answering
        // (the reader review, road map 4 §8, finding 1). The bound is
        // `snappedTick`'s own ±9.0e15, refused in a sentence naming the
        // argument. The sheet's two fields cannot reach it — they clamp to
        // `minLengthRange` and `paddingRange` — so the guard belongs here,
        // on the one caller that is not a slider.
        if let minLength = try intArg(a, "min_length") {
            guard minLength >= 0, minLength <= Self.durationCeiling else {
                throw ToolError(
                    message: "min_length must be a length in ticks (600000 per second) from 0 "
                        + "to \(Self.durationCeiling).")
            }
            settings.minLength = Ticks(minLength)
        }
        if let padding = try intArg(a, "padding") {
            guard padding >= 0, padding <= Self.durationCeiling else {
                throw ToolError(
                    message: "padding must be a length in ticks (600000 per second) from 0 "
                        + "to \(Self.durationCeiling).")
            }
            settings.padding = Ticks(padding)
        }
        return (settings, note)
    }
}
import AppKit

/// The agent's filler tools: `detect_fillers`, the read half of Clip ▸ Remove
/// Filler Words… (road map "cut-by-transcript" CT-2, CT-3) and the agent's
/// path to the cut (spec §11 TR-4, TR-9), and `transcribe_for_fillers`, the
/// mirror of that sheet's Transcribe button (TR-10).
///
/// `detect_fillers` is an APP-STATE tool, not an op — it changes nothing and
/// registers no undo step, as `detect_silence` does
/// (`AgentServer+Silence.swift`, whose posture this follows). The words are
/// a Swift cache (`cache/transcripts/`), so an agent that could only call
/// `ripple_delete_ranges` would have nothing to cut by; this answers the
/// ranges and `ripple_delete_ranges` makes the one undo step.
///
/// It stays on the MAIN thread, out of `AgentServer.offMainTools`, for
/// `detect_silence`'s reason: reading a few cached transcripts and one pass
/// of arithmetic waits on nothing and has no completion to deliver. It never
/// makes a network call: only a cached AssemblyAI transcript that asked for
/// filler words is read (TR-7). `transcribe_for_fillers` is the other
/// posture: a paid upload, off main (`AgentServer.offMainTools`), always
/// withheld from the assistant (AI-7 as TR-10 amends it).
extension AgentServer {

    /// `detect_fillers` — the read half of Clip ▸ Remove Filler Words…, and
    /// the agent's path. Nothing is edited: feed `ranges` to
    /// `ripple_delete_ranges` to make the cut.
    func detectFillers(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let clips = try optionalClipsArg(a, "clips", document)
        let input = FillerDetector.read(from: document, clips: clips)
        let outcome = FillerDetector.detect(input)

        var result: [String: Any] = [
            "ok": true,
            "ranges": outcome.spans.map { [$0.start, $0.end] },
            "count": outcome.spans.count,
            "removes": outcome.removed,
            "scope": outcome.scope.rawValue,
            "clips": outcome.clips.map { Int($0) },
            "fillers": outcome.candidates.map { candidate -> [String: Any] in
                [
                    "clip": Int(candidate.clip), "words": candidate.words,
                    "range": [candidate.span.start, candidate.span.end],
                ]
            },
            "dropped": outcome.dropped.map { drop -> [String: Any] in
                ["clip": Int(drop.clip), "words": drop.words, "reason": Self.sentence(drop.reason)]
            },
            "needs_transcript": outcome.needsTranscript.map { Int($0) },
            "locked": outcome.locked.map { Int($0) },
        ]
        if clips != nil, !outcome.skipped.isEmpty {
            result["skipped"] = outcome.skipped.map { $0.description }
        }
        var notes: [String] = []
        if outcome.clips.isEmpty, outcome.needsTranscript.isEmpty, outcome.locked.isEmpty {
            notes.append("Nothing in scope plays speech from a media file, so nothing was read.")
        }
        if !outcome.needsTranscript.isEmpty {
            notes.append(
                "Media \(Self.fillerList(outcome.needsTranscript)) has no transcript made with "
                    + "filler words, so its fillers cannot be found: filler removal needs an "
                    + "AssemblyAI transcript (spec §11 TR-7). transcribe_for_fillers makes "
                    + "one for a media, keeping its earlier request (a paid upload).")
        }
        if !outcome.locked.isEmpty {
            notes.append(
                "Clip \(Self.fillerList(outcome.locked)) is on a locked track, which "
                    + "ripple_delete_ranges neither cuts nor moves, so its fillers were not read.")
        }
        if !notes.isEmpty { result["note"] = notes.joined(separator: " ") }
        result["project"] = summary(document)
        return try jsonResult(result)
    }

    /// `transcribe_for_fillers` — the Transcribe button of Clip ▸ Remove
    /// Filler Words…' rows (`FillerSheetController+Transcribe.swift`): one
    /// media re-transcribed with AssemblyAI, with its previous request plus
    /// filler words (`FillerTranscription`, TR-10). Only the media's
    /// transcript cache is written: no caption is placed, no undo step made.
    ///
    /// Refused in this order, every step above the network: the media id,
    /// a document with nowhere to keep the cache, a media no clip plays from
    /// its file, then the credential; a media that already has a filler
    /// transcript answers with no request, between the last two.
    func transcribeForFillers(_ a: [String: Any]) throws -> String {
        guard !Thread.isMainThread else {
            throw ToolError(
                message: "transcribe_for_fillers must run on the server thread — its name is "
                    + "missing from AgentServer.offMainTools.")
        }
        struct Context {
            let document: ProjectDocument
            let media: UInt32
            let cache: URL
            let jobs: [Transcriber.Job]
            let records: [UInt32: MediaSnapshot]
            let ready: Bool
            let frame: Ticks
            let canvas: CGSize
        }
        let context = try onMain { () -> Context in
            let document = try self.target(a)
            let media = try self.mediaArg(a, "media", document)
            guard let cache = document.cacheDirectory else {
                throw ToolError(
                    message: "This document has nowhere to keep its transcript cache, so it "
                        + "cannot be transcribed with AssemblyAI. Save it first.")
            }
            let snapshot = document.editedProject.snapshot
            let jobs = FillerTranscription.jobs(
                for: media.id, in: snapshot, urls: document.mediaURLs(),
                maps: document.editedProject.sourceMap)
            guard let first = jobs.first else {
                throw ToolError(
                    message: "No clip in this timeline plays media \(media.id) from its file, so "
                        + "it cannot be transcribed.")
            }
            var records: [UInt32: MediaSnapshot] = [:]
            for entry in snapshot.media { records[entry.id] = entry }
            return Context(
                document: document, media: media.id, cache: cache, jobs: jobs, records: records,
                ready: Self.fillersReady(media, url: first.source, cache: cache),
                frame: max(snapshot.canvas.fps.frameDuration, 1),
                canvas: CGSize(width: snapshot.canvas.width, height: snapshot.canvas.height))
        }
        let options = FillerTranscription.options(
            for: MediaTranscript.readStamp(for: context.media, in: context.cache))

        var result: [String: Any]
        if context.ready {
            var report = CloudTranscriber.Report()
            report.cached = [context.media]
            result = Self.cloudFields(
                report, code: options.languageCode, endpoint: nil,
                notes: [
                    "Media \(context.media) already has a transcript made with filler words, so "
                        + "nothing was uploaded."
                ])
            result["ready"] = true
        } else {
            guard
                let credential = AssemblyAIConfiguration.credential(
                    store: AssemblyAIConfiguration.store())
            else {
                throw ModelKeys.refusal(.assemblyAI)
            }
            let client: AssemblyAIClient
            do {
                client = AssemblyAIClient(
                    base: try AssemblyAIConfiguration.baseURL(), credential: credential)
            } catch {
                throw ToolError(message: error.localizedDescription)
            }
            let transcriber = CloudTranscriber(
                client: client, cacheDirectory: context.cache, media: context.records)
            do {
                _ = try transcriber.transcribe(
                    context.jobs, options: options, refresh: FillerTranscription.refresh,
                    frame: context.frame,
                    pages: CaptionPages.Request(style: .subtitles, canvas: context.canvas),
                    cancel: Transcriber.CancelToken())
            } catch {
                throw ToolError(message: Self.cloudFailure(error, report: transcriber.report))
            }
            result = Self.cloudFields(
                transcriber.report, code: options.languageCode, endpoint: client.base.host,
                notes: [])
        }
        return try onMain {
            if !context.ready {
                // Asked again: the run's answer is what the cache holds now.
                let media = context.document.editedProject.snapshot.media(context.media)
                result["ready"] = media.map {
                    Self.fillersReady($0, url: context.jobs[0].source, cache: context.cache)
                } ?? false
            }
            result["ok"] = true
            result["media"] = Int(context.media)
            result["project"] = self.summary(context.document)
            return try self.jsonResult(result)
        }
    }

    /// Whether the media now has a transcript `FillerDetector` reads.
    private static func fillersReady(_ media: MediaSnapshot, url: URL, cache: URL) -> Bool {
        FillerDetector.fillersFile(for: media, url: url, in: cache) != nil
    }

    /// A drop reason as the answer's sentence.
    private static func sentence(_ reason: FillerDetector.DropReason) -> String {
        switch reason {
        case .tooShort:
            return "too short to cut once its edges are on the 32 ms grid and the frame grid"
        case .overlapsWord(let clip, let text):
            return "it overlaps \"\(text)\" in clip \(clip)"
        case .nest(let clip):
            return "it crosses nest clip \(clip), which a cut must not split"
        case .transition:
            return "it crosses a transition"
        }
    }

    /// "3, 7, 9".
    private static func fillerList(_ ids: [UInt32]) -> String {
        ids.map { String($0) }.joined(separator: ", ")
    }
}

import Foundation

/// Remove Filler Words' detector (road map "cut-by-transcript" CT-2, spec §11
/// TR-4, TR-7, TR-9): a clip's cached cloud filler words as project ranges
/// `ripple_delete_ranges` cuts, every edge on the Silero 32 ms grid and then
/// on the frame grid.
///
/// `SilenceDetector`'s shape: `read(from:clips:)` is the one seam that touches
/// a document — its snapshot, its selection, its media URLs and the transcript
/// cache, read ONCE — and everything after it (`runs`, `gridded`, `placed`,
/// `detect`) is arithmetic over values. The words are a Swift cache like the
/// peaks (spec §7), so nothing here crosses the FFI.
///
/// **Only a transcript that asked for fillers is read** (TR-7): the scope's
/// files come through `fillersFile`, whose marker must serve `.fillers`
/// (TR-2's one rule, `TranscriptStamp.serves`). A media without one is named
/// in `needsTranscript` and gives no candidate. The NEIGHBOURS' words — which
/// protect a span from a cut — are taken from any transcript that serves
/// `.captions`, because a word is a word whichever request heard it.
///
/// **TR-9, the edges.** A run of consecutive fillers is widened OUTWARD to the
/// grid so the whole filler goes, but never past the words beside it; each
/// edge then maps to project time through `MediaTranscript.project` (R6-10's
/// door) and snaps INWARD to the frame grid, as Remove Silences snaps. A
/// candidate that would cut into another clip's word, a nest clip or a
/// transition is dropped whole, never trimmed, so every kept edge is a grid
/// edge.
enum FillerDetector {

    /// The Silero VAD's chunk in source ticks (512 samples at 16 kHz), from
    /// absolute source time 0 — the speech cache's own index.
    static var grid: Ticks { MediaSpeech.chunkTicks }

    /// Which clips were read: the ones named or selected, or every clip.
    enum Scope: String { case selected, all }

    /// One clip's job and the transcript file of its media.
    struct ClipWords {
        let job: Transcriber.Job
        let file: MediaTranscript.File
    }

    /// Everything a detection reads, taken off the document once.
    struct Input {
        let fps: Fps
        let scope: Scope
        /// The scope's clips whose media has a transcript that asked for fillers.
        let clips: [ClipWords]
        /// Media ids in scope with no such transcript, sorted and distinct.
        let needsTranscript: [UInt32]
        /// The named clips `Transcriber.jobs` refused, each with its reason.
        let skipped: [CaptionLayout.Problem]
        /// In-scope clip ids on locked tracks, sorted: the ripple neither cuts
        /// nor moves a locked track, so their fillers are not read.
        let locked: [UInt32]
        /// Every top-level clip on an unlocked track whose media's transcript
        /// serves `.captions`, in scope or not: the ripple cuts every
        /// unlocked track, so their words protect a span.
        let neighbours: [ClipWords]
        let nests: [SilenceDetector.NestExtent]
        let walls: [SilenceDetector.Span]
    }

    /// One run of consecutive fillers in a clip's word order, in source ticks.
    struct Run: Equatable {
        let words: [String]
        let source: SilenceDetector.Span
        /// The latest end of a non-filler word before the run, or the clip's `in`.
        let previousEnd: Ticks
        /// The earliest start of a non-filler word after it, or the window's end.
        let nextStart: Ticks
    }

    /// A run that became a cut: its source span on the grid and its project span.
    struct Candidate: Equatable {
        let clip: UInt32
        let words: [String]
        let source: SilenceDetector.Span
        let span: SilenceDetector.Span
    }

    enum DropReason: Equatable {
        case tooShort
        case overlapsWord(clip: UInt32, text: String)
        case nest(clip: UInt32)
        case transition
    }

    struct Dropped: Equatable {
        let clip: UInt32
        let words: [String]
        let reason: DropReason
    }

    struct Outcome {
        /// The kept candidates merged where they overlap or touch.
        let spans: [SilenceDetector.Span]
        let candidates: [Candidate]
        let dropped: [Dropped]
        let scope: Scope
        /// The clips whose words were read, sorted.
        let clips: [UInt32]
        let needsTranscript: [UInt32]
        let skipped: [CaptionLayout.Problem]
        let locked: [UInt32]

        var removed: Ticks { spans.reduce(0) { $0 + $1.length } }
    }

    // MARK: - The read

    /// The document's snapshot, scope and transcript cache, read once.
    ///
    /// Named clips are the scope (`.selected`); with none named, the
    /// selection when `Transcriber.jobs` accepts any of it, else every clip.
    /// The EDITED project, as `SilenceDetector.read` takes it: with a nest
    /// open the ranges are the nest's, in the nest's own time.
    static func read(from document: ProjectDocument, clips named: [UInt32]?) -> Input {
        let snapshot = document.editedProject.snapshot
        let urls = document.mediaURLs()
        let maps = document.editedProject.sourceMap
        let scope: Scope
        let chosen: [ClipSnapshot]
        if let named {
            let ids = Set(named)
            chosen = snapshot.clips.filter { ids.contains($0.id) }
            scope = .selected
        } else {
            let selected = snapshot.clips.filter { document.selection.contains($0.id) }
            if !Transcriber.jobs(for: selected, in: snapshot, urls: urls, maps: maps).jobs.isEmpty {
                chosen = selected
                scope = .selected
            } else {
                chosen = snapshot.clips
                scope = .all
            }
        }
        let (kept, locked) = onUnlockedTracks(chosen, in: snapshot)
        let (jobs, problems) = Transcriber.jobs(for: kept, in: snapshot, urls: urls, maps: maps)
        let cacheDirectory = document.cacheDirectory

        var clips: [ClipWords] = []
        var needs: Set<UInt32> = []
        var scopeFiles: [UInt32: MediaTranscript.File?] = [:]
        for job in jobs {
            if scopeFiles[job.media] == nil {
                scopeFiles[job.media] = .some(
                    cacheDirectory.flatMap { cache in
                        snapshot.media(job.media).flatMap {
                            fillersFile(for: $0, url: job.source, in: cache)
                        }
                    })
            }
            if let file = scopeFiles[job.media] ?? nil {
                clips.append(ClipWords(job: job, file: file))
            } else {
                needs.insert(job.media)
            }
        }

        var neighbours: [ClipWords] = []
        if let cacheDirectory {
            let unlocked = onUnlockedTracks(snapshot.clips, in: snapshot).kept
            var files: [UInt32: MediaTranscript.File?] = [:]
            let found = Transcriber.jobs(for: unlocked, in: snapshot, urls: urls, maps: maps)
            for job in found.jobs {
                if files[job.media] == nil {
                    files[job.media] = .some(
                        snapshot.media(job.media).flatMap {
                            transcriptFile(
                                for: $0, url: job.source, in: cacheDirectory, use: .captions)
                        })
                }
                if let file = files[job.media] ?? nil {
                    neighbours.append(ClipWords(job: job, file: file))
                }
            }
        }
        return Input(
            fps: snapshot.canvas.fps, scope: scope, clips: clips, needsTranscript: needs.sorted(),
            skipped: named == nil ? [] : problems, locked: locked, neighbours: neighbours,
            nests: SilenceDetector.nestExtents(in: snapshot),
            walls: SilenceDetector.overlapWalls(snapshot))
    }

    /// The scope's door: a media's transcript only when its marker serves
    /// filler removal (TR-7, TR-2).
    static func fillersFile(
        for media: MediaSnapshot, url: URL, in cacheDir: URL
    ) -> MediaTranscript.File? {
        transcriptFile(for: media, url: url, in: cacheDir, use: .fillers)
    }

    /// A media's cached transcript when the file as it is NOW stamps the
    /// marker's source, the file reads, and the marker serves `use` for the
    /// request the file records; else nil.
    static func transcriptFile(
        for media: MediaSnapshot, url: URL, in cacheDir: URL, use: TranscriptUse
    ) -> MediaTranscript.File? {
        guard let stamp = MediaImporter.CacheStamp.stamp(for: media, url: url),
            let file = MediaTranscript.read(for: media.id, in: cacheDir),
            let marker = MediaTranscript.readStamp(for: media.id, in: cacheDir),
            marker.serves(TranscriptStamp(source: stamp, options: file.header.requested), for: use)
        else { return nil }
        return file
    }

    /// The clips not on a locked track, and the ids of those that are,
    /// sorted. A track the snapshot cannot find counts as unlocked, as the
    /// nest walls read it.
    static func onUnlockedTracks(
        _ clips: [ClipSnapshot], in snapshot: ProjectSnapshot
    ) -> (kept: [ClipSnapshot], locked: [UInt32]) {
        var kept: [ClipSnapshot] = []
        var locked: [UInt32] = []
        for clip in clips {
            if snapshot.track(clip.track)?.locked == true {
                locked.append(clip.id)
            } else {
                kept.append(clip)
            }
        }
        return (kept, locked.sorted())
    }

    // MARK: - The arithmetic

    /// One word of a clip's window, in source ticks.
    private struct Timed {
        let text: String
        let start: Ticks
        let end: Ticks
        let filler: Bool
    }

    /// The clip's words in source ticks: those whose start is in its window
    /// (R6-10), sorted by start then end.
    private static func timed(_ file: MediaTranscript.File, in job: Transcriber.Job) -> [Timed] {
        let windowEnd = job.sourceIn + job.sourceLength
        var out: [Timed] = []
        for word in file.words {
            let start = MediaTranscript.sourceTicks(milliseconds: word.start)
            guard start >= job.sourceIn, start < windowEnd else { continue }
            out.append(
                Timed(
                    text: word.text, start: start,
                    end: MediaTranscript.sourceTicks(milliseconds: max(word.start, word.end)),
                    filler: FillerWords.isFiller(word.text)))
        }
        return out.sorted { ($0.start, $0.end) < ($1.start, $1.end) }
    }

    /// Every maximal run of consecutive fillers in the clip's word order,
    /// with the non-filler words that bound it (TR-9).
    static func runs(of file: MediaTranscript.File, in job: Transcriber.Job) -> [Run] {
        let words = timed(file, in: job)
        let windowEnd = job.sourceIn + job.sourceLength
        // The latest non-filler end before each index, and the earliest
        // non-filler start after it.
        var before = [Ticks](repeating: job.sourceIn, count: words.count + 1)
        for (index, word) in words.enumerated() {
            before[index + 1] = word.filler ? before[index] : max(before[index], word.end)
        }
        var after = [Ticks](repeating: windowEnd, count: words.count + 1)
        for index in stride(from: words.count - 1, through: 0, by: -1) {
            let word = words[index]
            after[index] = word.filler ? after[index + 1] : min(after[index + 1], word.start)
        }
        var runs: [Run] = []
        var open: [Int] = []
        func close() {
            guard let first = open.first, let last = open.last else { return }
            runs.append(
                Run(
                    words: open.map { words[$0].text },
                    source: SilenceDetector.Span(
                        start: words[first].start, end: open.map { words[$0].end }.max() ?? 0),
                    previousEnd: before[first], nextStart: after[last + 1]))
            open = []
        }
        for (index, word) in words.enumerated() {
            guard word.filler else {
                close()
                continue
            }
            open.append(index)
        }
        close()
        return runs
    }

    private static func down(_ t: Ticks, _ grid: Ticks) -> Ticks {
        let q = t / grid
        return (t % grid != 0 && t < 0 ? q - 1 : q) * grid
    }

    private static func up(_ t: Ticks, _ grid: Ticks) -> Ticks {
        let q = t / grid
        return (t % grid != 0 && t > 0 ? q + 1 : q) * grid
    }

    /// A run's source span widened outward to the grid, bounded by its
    /// neighbours' grid points inward; nil when nothing is left.
    static func gridded(_ run: Run, grid: Ticks) -> SilenceDetector.Span? {
        guard grid > 0 else { return nil }
        let start = max(down(run.source.start, grid), up(run.previousEnd, grid))
        let end = min(up(run.source.end, grid), down(run.nextStart, grid))
        guard end > start else { return nil }
        return SilenceDetector.Span(start: start, end: end)
    }

    /// A source span in project time, its start snapped up and its end down
    /// to the frame grid; nil when nothing is left.
    static func placed(
        _ source: SilenceDetector.Span, in job: Transcriber.Job, fps: Fps
    ) -> SilenceDetector.Span? {
        let span = SilenceDetector.Span(
            start: SilenceDetector.snapUpToFrame(
                MediaTranscript.project(source.start, in: job), fps: fps),
            end: SilenceDetector.snapDownToFrame(
                MediaTranscript.project(source.end, in: job), fps: fps))
        guard span.end > span.start else { return nil }
        return span
    }

    // MARK: - Detection

    /// The candidates, what was dropped and why, and the merged ranges.
    static func detect(_ input: Input) -> Outcome {
        // Every neighbour's non-filler words in project time, read once.
        let guarded: [(clip: UInt32, words: [CaptionCues.Word])] = input.neighbours.map {
            ($0.job.clip,
             MediaTranscript.words(for: $0.job, in: $0.file).filter {
                 !FillerWords.isFiller($0.text)
             })
        }
        var candidates: [Candidate] = []
        var dropped: [Dropped] = []
        for clip in input.clips {
            let id = clip.job.clip
            for run in runs(of: clip.file, in: clip.job) {
                guard let source = gridded(run, grid: grid),
                    let span = placed(source, in: clip.job, fps: input.fps)
                else {
                    dropped.append(Dropped(clip: id, words: run.words, reason: .tooShort))
                    continue
                }
                if let reason = conflict(span, clip: id, guarded: guarded, input: input) {
                    dropped.append(Dropped(clip: id, words: run.words, reason: reason))
                    continue
                }
                candidates.append(Candidate(clip: id, words: run.words, source: source, span: span))
            }
        }
        return Outcome(
            spans: SilenceDetector.merged(candidates.map(\.span)), candidates: candidates,
            dropped: dropped, scope: input.scope,
            clips: Set(input.clips.map { $0.job.clip }).sorted(),
            needsTranscript: input.needsTranscript, skipped: input.skipped, locked: input.locked)
    }

    /// Why a span may not be cut, in TR-9's order: another clip's word, a
    /// nest clip, a transition wall; nil when it may.
    private static func conflict(
        _ span: SilenceDetector.Span, clip: UInt32,
        guarded: [(clip: UInt32, words: [CaptionCues.Word])], input: Input
    ) -> DropReason? {
        for neighbour in guarded where neighbour.clip != clip {
            if let word = neighbour.words.first(where: {
                SilenceDetector.overlap(span, SilenceDetector.Span(start: $0.start, end: $0.end)) > 0
            }) {
                return .overlapsWord(clip: neighbour.clip, text: word.text)
            }
        }
        if let nest = input.nests.first(where: { SilenceDetector.overlap(span, $0.span) > 0 }) {
            return .nest(clip: nest.clip)
        }
        if input.walls.contains(where: { SilenceDetector.overlap(span, $0) > 0 }) {
            return .transition
        }
        return nil
    }
}
